/**
 * Operações HTTP do recurso pedidos.
 */
import { apiRequest } from "../../../../support/api/client.js";

export function listarPedidos() {
  return apiRequest({ method: "GET", url: "/pedidos" });
}

export function criarPedido(corpo) {
  return apiRequest({ method: "POST", url: "/pedidos", body: corpo });
}

/**
 * Pedidos — fluxo principal de listagem e criação.
 */
import { criarPedido, listarPedidos } from "./_support/api.js";

describe("pedidos — fluxo principal", () => {
  // @endpoint GET /pedidos @cat CAT-01 @alvo listagem-devolve-colecao
  it("lista pedidos e devolve a coleção", () => {
    listarPedidos().then((resposta) => {
      expect(resposta.status, "status da listagem de pedidos").to.eq(200);
      expect(resposta.body, "corpo da listagem de pedidos").to.be.an("array");
    });
  });

  // @endpoint POST /pedidos @cat CAT-01 @alvo criacao-persistida
  it("cria um pedido e devolve o registro criado", () => {
    criarPedido({ situacao: "ABERTO" }).then((resposta) => {
      expect(resposta.status, "status da criação de pedido").to.eq(201);
      expect(resposta.body.situacao, "situação do pedido criado").to.eq("ABERTO");
    });
  });
});

/**
 * Pedidos — validações da superfície de entrada da criação.
 */
import { criarPedido } from "./_support/api.js";

describe("pedidos — validações", () => {
  // @endpoint POST /pedidos @cat CAT-02 @campo situacao @alvo situacao-ausente
  it("recusa a criação quando situacao é omitida", () => {
    criarPedido({}).then((resposta) => {
      expect(resposta.status, "status ao omitir situacao").to.eq(400);
    });
  });

  // @endpoint POST /pedidos @cat CAT-05 @alvo corpo-escalar
  it("recusa corpo escalar na criação", () => {
    criarPedido("texto").then((resposta) => {
      expect(resposta.status, "status ao enviar corpo escalar").to.eq(400);
    });
  });
});
